 1	/* ============================================================
 2	   views/strategy.js — Strategy view (Repository List + Detail/Editor)
 3	   Section 4g of the MCP Server Dashboard SPA
 4	   Depends on: API, Router, escapeHtml, showLoading, showError
 5	   ============================================================ */
 6	
 7	
 8	/* ── renderStrategyList ──────────────────────────────────────
 9	   Renders the repository list at #/strategy.
10	   Shows: label, folder names, vision status; Add Repository form.
11	   ─────────────────────────────────────────────────────────── */
12	function renderStrategyList(app) {
13	  showLoading(app);
14	
15	  API.listRepos().then(function (repos) {
16	    renderList(repos);
17	  }).catch(function (err) {
18	    showError(app, 'Failed to load repositories: ' + (err.message || String(err)));
19	  });
20	
21	  function visionStatus(repo) {
22	    if (!repo.has_vision) return '<span class="badge badge-blocked">No vision</span>';
23	    return repo.has_full_vision
24	      ? '<span class="badge badge-complete">Full vision</span>'
25	      : '<span class="badge badge-in-progress">Partial vision</span>';
26	  }
27	
28	  function buildTableHtml(repos) {
29	    if (!repos.length) {
30	      return '<p class="text-muted mt-16">No repositories declared yet. Use the form below to add one.</p>';
31	    }
32	    var rows = repos.map(function (r) {
33	      var folderNames = (r.folder_names || []).map(escapeHtml).join(', ') || '<em class="text-muted">—</em>';
34	      return (
35	        '<tr>' +
36	          '<td><a href="#/strategy/' + encodeURIComponent(r.id) + '">' + escapeHtml(r.label || r.id) + '</a></td>' +
37	          '<td class="text-muted">' + escapeHtml(r.id) + '</td>' +
38	          '<td>' + folderNames + '</td>' +
39	          '<td>' + visionStatus(r) + '</td>' +
40	        '</tr>'
41	      );
42	    }).join('');
43	    return (
44	      '<table class="data-table">' +
45	        '<thead><tr>' +
46	          '<th>Label</th>' +
47	          '<th>ID</th>' +
48	          '<th>Folder Names</th>' +
49	          '<th>Vision</th>' +
50	        '</tr></thead>' +
51	        '<tbody>' + rows + '</tbody>' +
52	      '</table>'
53	    );
54	  }
55	
56	  function renderList(repos) {
57	    app.innerHTML =
58	      '<div class="page-header">' +
59	        '<h1>Strategy</h1>' +
60	        '<p class="text-muted">Manage repository declarations and strategic vision.</p>' +
61	      '</div>' +
62	      buildTableHtml(repos) +
63	      '<div class="card mt-24" style="max-width:560px">' +
64	        '<h2 style="margin-top:0">Add Repository</h2>' +
65	        '<form id="add-repo-form">' +
66	          '<div class="form-group">' +
67	            '<label class="form-label" for="new-repo-id">ID <span class="text-muted">(slug, e.g. my-project)</span></label>' +
68	            '<input type="text" id="new-repo-id" class="form-control" placeholder="my-project" required>' +
69	          '</div>' +
70	          '<div class="form-group">' +
71	            '<label class="form-label" for="new-repo-label">Label</label>' +
72	            '<input type="text" id="new-repo-label" class="form-control" placeholder="My Project">' +
73	          '</div>' +
74	          '<div class="form-group">' +
75	            '<label class="form-label" for="new-repo-folders">Folder Names <span class="text-muted">(comma-separated)</span></label>' +
76	            '<input type="text" id="new-repo-folders" class="form-control" placeholder="my-project, my-project-dev">' +
77	          '</div>' +
78	          '<button type="submit" class="btn btn-primary">Add Repository</button>' +
79	          '<div id="add-repo-msg"></div>' +
80	        '</form>' +
81	      '</div>';
82	
83	    var form = document.getElementById('add-repo-form');
84	    if (!form) return;
85	
86	    form.addEventListener('submit', function (e) {
87	      e.preventDefault();
88	      var msgEl = document.getElementById('add-repo-msg');
89	      var id = (document.getElementById('new-repo-id').value || '').trim();
90	      var label = (document.getElementById('new-repo-label').value || '').trim();
91	      var foldersRaw = (document.getElementById('new-repo-folders').value || '').trim();
92	      var folderNames = foldersRaw
93	        ? foldersRaw.split(',').map(function (f) { return f.trim(); }).filter(Boolean)
94	        : [];
95	
96	      if (!id) {
97	        msgEl.innerHTML = '<p class="error-banner">ID is required.</p>';
98	        return;
99	      }

100	
101	      msgEl.innerHTML = '';
102	      API.createRepo({ id: id, label: label || id, folder_names: folderNames })
103	        .then(function () {
104	          Router.navigate('#/strategy/' + encodeURIComponent(id));
105	        })
106	        .catch(function (err) {
107	          msgEl.innerHTML = '<p class="error-banner">Failed to create repository: ' + escapeHtml(err.message || String(err)) + '</p>';
